insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('poulet-tikka-chou-fleur-roti', 'Poulet tikka au four et chou-fleur rôti', 'Des morceaux de poulet marinés au yaourt, gingembre, curry et paprika, rôtis au four avec des bouquets de chou-fleur. Toutes les saveurs du poulet tikka, sans crème et sans friture.', 'Se garde 3 jours au réfrigérateur. Se réchauffe 10 minutes au four à 180 °C.', 2, 15, 30, array['plat', 'four', 'monde']::text[]),
  ('saumon-laque-riz-complet-haricots', 'Saumon laqué au miel et au soja, riz complet et haricots verts', 'Un pavé de saumon laqué d''une sauce miel, soja et gingembre, cuit au four, avec du riz complet et des haricots verts au sésame. Sucré-salé, brillant et prêt en 30 minutes.', 'Se garde 2 jours au réfrigérateur. Se mange aussi froid, émietté sur le riz.', 2, 10, 25, array['plat', 'four']::text[]),
  ('fajitas-dinde-haricots-rouges', 'Fajitas de dinde, poivrons et haricots rouges', 'Des lanières de dinde épicées, des poivrons et de l''oignon saisis, des haricots rouges, servis dans des tortillas avec une sauce au yaourt et au citron vert. Généreux et plein de protéines.', 'La garniture se garde 2 jours au réfrigérateur ; garnir les tortillas au moment de servir.', 2, 15, 15, array['plat', 'poele', 'monde']::text[]),
  ('tajine-poulet-pois-chiches-carottes', 'Tajine de poulet aux pois chiches et carottes', 'Un tajine parfumé au cumin, à la cannelle et au gingembre, avec du poulet, des carottes fondantes et des pois chiches, servi avec un peu de semoule. Idéal à préparer en grande quantité.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois. Encore meilleur réchauffé.', 4, 20, 40, array['plat', 'mijote', 'batch-cooking', 'monde']::text[]),
  ('crevettes-haricots-blancs-tomates-epinards', 'Crevettes, haricots blancs, tomates et épinards à l''ail', 'Des crevettes saisies à l''ail, puis mijotées quelques minutes avec des haricots blancs, des tomates et des épinards. Un plat de poêle façon toscane, rapide et très complet.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement pour ne pas durcir les crevettes.', 2, 10, 15, array['plat', 'poele', 'economique']::text[]),
  ('gratin-cabillaud-poireaux-pommes-de-terre', 'Gratin de cabillaud, poireaux et pommes de terre', 'Du cabillaud, des poireaux fondus et des pommes de terre, nappés d''une sauce au fromage blanc et gratinés à l''emmental. Tout le réconfort d''un gratin, en beaucoup plus léger.', 'Se garde 2 jours au réfrigérateur. Réchauffer au four à 160 °C.', 2, 20, 35, array['plat', 'four']::text[]),
  ('porc-saute-chou-gingembre-riz', 'Porc sauté au chou et au gingembre, riz basmati', 'Des lamelles de filet mignon sautées avec du chou vert émincé, du gingembre et de la sauce soja, servies sur du riz basmati. Simple, croquant et économique.', 'Se garde 2 jours au réfrigérateur. Réchauffer 2 minutes à la poêle.', 2, 15, 15, array['plat', 'poele', 'economique']::text[]),
  ('dinde-curry-epinards-basmati', 'Dinde au curry doux, épinards et riz basmati', 'Des morceaux de dinde dans une sauce au curry, au yaourt et à la tomate, avec des épinards fondus et du riz basmati. Un curry léger et doux qui plaît à tout le monde.', 'Se garde 3 jours au réfrigérateur et se congèle 2 mois (sans le riz).', 2, 10, 25, array['plat', 'mijote', 'monde']::text[]),
  ('gratin-pates-completes-thon-brocoli', 'Gratin de pâtes complètes au thon et brocoli', 'Des pâtes complètes, du thon et du brocoli dans une sauce légère au fromage blanc, gratinés à l''emmental. Un plat familial qui se prépare à l''avance et se réchauffe très bien.', 'Se garde 4 jours au réfrigérateur et se congèle 2 mois, en portions.', 4, 15, 25, array['plat', 'four', 'batch-cooking', 'economique']::text[]),
  ('buddha-bowl-tofu-patate-douce', 'Buddha bowl tofu mariné, patate douce et chou rouge', 'Du tofu mariné au soja et rôti, des cubes de patate douce, du chou rouge cru et du quinoa, avec une sauce au yaourt et au sésame. Coloré, croquant et rassasiant.', 'Se garde 2 jours au réfrigérateur, la sauce à part.', 2, 20, 30, array['plat', 'four']::text[]),
  ('soupe-lentilles-corail-poulet', 'Soupe-repas de lentilles corail au poulet et au cumin', 'Une soupe épaisse et réconfortante de lentilles corail, carottes et tomates au cumin, avec du poulet effiloché. Un vrai repas complet en un bol.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 15, 35, array['soupe', 'mijote', 'batch-cooking', 'economique']::text[]),
  ('pates-completes-poulet-epinards', 'Pâtes complètes au poulet, épinards et parmesan', 'Des pâtes complètes, du poulet poêlé et des épinards, liés par une sauce onctueuse au fromage blanc, à l''ail et au parmesan. Le plaisir d''un plat de pâtes crémeux, en plus léger.', 'Se garde 2 jours au réfrigérateur. Réchauffer avec un trait d''eau.', 2, 10, 15, array['plat', 'poele']::text[]),
  ('overnight-oats-fromage-blanc-myrtilles', 'Overnight oats au fromage blanc et aux myrtilles', 'Des flocons d''avoine trempés une nuit dans du lait et du fromage blanc, avec des myrtilles et des amandes. Un petit-déjeuner prêt au réveil, rassasiant jusqu''au midi.', 'Se garde 2 jours au réfrigérateur, sans les fruits ni les amandes.', 2, 5, 0, array['petit-dejeuner', 'sans-cuisson']::text[]),
  ('salade-poulet-haricots-verts-oeuf', 'Salade de poulet, haricots verts, œuf et pommes de terre', 'Une grande salade complète : poulet poêlé, haricots verts, pommes de terre tièdes, œufs durs et tomates, à la vinaigrette moutardée. Comme une niçoise, version plus protéinée.', 'Se garde 1 jour au réfrigérateur, la vinaigrette à part.', 2, 15, 20, array['salade', 'plat']::text[]),
  ('cabillaud-tomates-olives-semoule', 'Cabillaud mijoté aux tomates et olives, semoule', 'Du cabillaud cuit doucement dans une sauce tomate aux olives, à l''ail et aux herbes de Provence, servi avec de la semoule. Un parfum de Méditerranée en 25 minutes.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement à couvert.', 2, 10, 20, array['plat', 'poele']::text[]),
  ('poulet-moutarde-haricots-verts-vapeur', 'Poulet à la moutarde, haricots verts et pommes de terre vapeur', 'Des filets de poulet dorés, nappés d''une sauce minute à la moutarde et au fromage blanc, avec des haricots verts et des pommes de terre vapeur. Un classique allégé.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement, sans faire bouillir la sauce.', 2, 10, 25, array['plat', 'poele']::text[]),
  ('brochettes-dinde-taboule-herbes', 'Brochettes de dinde et taboulé de boulgour aux herbes', 'Des brochettes de dinde aux herbes de Provence et au citron, grillées à la poêle, avec un taboulé de boulgour très riche en persil, menthe, tomate et concombre.', 'Le taboulé se garde 2 jours au réfrigérateur ; les brochettes 2 jours, à manger froides ou réchauffées.', 2, 20, 15, array['plat', 'poele']::text[]),
  ('quiche-sans-pate-thon-courgettes', 'Quiche sans pâte au thon et aux courgettes', 'Une quiche sans pâte au thon, aux courgettes et au fromage blanc, moelleuse et très légère, qui se mange chaude ou froide avec une salade. Parfaite pour les lunchs.', 'Se garde 4 jours au réfrigérateur. Se mange froide ou réchauffée 1 minute au micro-ondes.', 4, 15, 35, array['plat', 'four', 'batch-cooking', 'economique']::text[]),
  ('tofu-brouille-epinards-pois-chiches', 'Tofu brouillé aux épinards et pois chiches', 'Du tofu émietté et poêlé au curcuma et au cumin, avec des pois chiches, des épinards et des tomates cerises. Une poêlée rapide et rassasiante, sans œufs.', 'Se garde 2 jours au réfrigérateur. Réchauffer 2 minutes à la poêle.', 2, 10, 15, array['plat', 'poele', 'economique']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

