  ('brochettes-dinde-taboule-herbes', 6, 'Cuire les brochettes 8 à 10 minutes dans une poêle chaude, en les retournant : elles doivent être dorées et cuites à cœur.'),
  ('brochettes-dinde-taboule-herbes', 7, 'Servir les brochettes sur le taboulé.'),
  ('quiche-sans-pate-thon-courgettes', 1, 'Préchauffer le four à 180 °C.'),
  ('quiche-sans-pate-thon-courgettes', 2, 'Râper les courgettes, les saler et les laisser dégorger 10 minutes, puis les presser entre les mains pour retirer l''eau.'),
  ('quiche-sans-pate-thon-courgettes', 3, 'Éplucher et émincer l''oignon, puis le faire revenir 5 minutes dans l''huile à feu moyen.'),
  ('quiche-sans-pate-thon-courgettes', 4, 'Dans un saladier, battre les œufs avec le fromage blanc, les herbes, du sel et du poivre.'),
  ('quiche-sans-pate-thon-courgettes', 5, 'Ajouter les courgettes, l''oignon, le thon égoutté et émietté et l''emmental râpé, et mélanger.'),
  ('quiche-sans-pate-thon-courgettes', 6, 'Verser dans un moule huilé et enfourner 35 minutes : la quiche doit être dorée et prise au centre.'),
  ('quiche-sans-pate-thon-courgettes', 7, 'Servir tiède ou froide avec la salade.'),
  ('tofu-brouille-epinards-pois-chiches', 1, 'Éplucher et émincer l''oignon.'),
  ('tofu-brouille-epinards-pois-chiches', 2, 'Faire chauffer l''huile dans une grande poêle à feu moyen et faire revenir l''oignon 5 minutes.'),
  ('tofu-brouille-epinards-pois-chiches', 3, 'Émietter le tofu à la fourchette et l''ajouter avec le curcuma et le cumin. Cuire 5 minutes en remuant, jusqu''à ce qu''il soit doré.'),
  ('tofu-brouille-epinards-pois-chiches', 4, 'Ajouter les pois chiches égouttés et les tomates cerises coupées en deux, et cuire 3 minutes.'),
  ('tofu-brouille-epinards-pois-chiches', 5, 'Ajouter les épinards et mélanger jusqu''à ce qu''ils tombent. Saler et poivrer.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('poulet-tikka-chou-fleur-roti', 'saumon-laque-riz-complet-haricots', 'fajitas-dinde-haricots-rouges', 'tajine-poulet-pois-chiches-carottes', 'crevettes-haricots-blancs-tomates-epinards', 'gratin-cabillaud-poireaux-pommes-de-terre', 'porc-saute-chou-gingembre-riz', 'dinde-curry-epinards-basmati', 'gratin-pates-completes-thon-brocoli', 'buddha-bowl-tofu-patate-douce', 'soupe-lentilles-corail-poulet', 'pates-completes-poulet-epinards', 'overnight-oats-fromage-blanc-myrtilles', 'salade-poulet-haricots-verts-oeuf', 'cabillaud-tomates-olives-semoule', 'poulet-moutarde-haricots-verts-vapeur', 'brochettes-dinde-taboule-herbes', 'quiche-sans-pate-thon-courgettes', 'tofu-brouille-epinards-pois-chiches')) <> 192 then
    raise exception 'Lignes d''ingrédients manquantes dans le septième lot de recettes.';
  end if;
end;
$$;
